using System.Globalization;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using BAL.AI;
using Utils;

namespace BAL.Assistant;

/// <summary>
/// Every assistant reply (or a whole chat) as a file: PDF, Excel, CSV, Markdown or JSON. Built from the saved blocks —
/// the same figures that were on screen — never regenerated by the model.
/// </summary>
public static class Downloads
{
    public static readonly Dictionary<string, string> Formats = new()
    {
        ["pdf"] = "application/pdf", ["xlsx"] = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        ["csv"] = "text/csv; charset=utf-8", ["md"] = "text/markdown; charset=utf-8", ["json"] = "application/json",
    };

    private static readonly CultureInfo Inv = CultureInfo.InvariantCulture;

    private static string Now(string fmt) => DateTimeFunctions.ToIst(DateTimeFunctions.UtcNow()).ToString(fmt, Inv);

    private static IList<object?> Cells(JsonNode? row) => (row as JsonArray ?? []).Select(c => (object?)(c is JsonValue v && v.GetValueKind() == JsonValueKind.Number
        ? (v.ToJsonString().Contains('.') ? J.Double(v) : J.Long(v)) : c is null ? "" : J.S(c))).ToList();

    private static List<(string Title, IList<string> Columns, IList<IList<object?>> Rows)> Tables(IEnumerable<JsonObject> blocks)
    {
        var outp = new List<(string, IList<string>, IList<IList<object?>>)>();
        foreach (var b in blocks)
        {
            var t = J.S(b["type"]);
            var title = J.S(b["title"]);
            if (t == "table")
                outp.Add((title.Length > 0 ? title : "Table", (b["columns"] as JsonArray ?? []).Select(J.S).ToList(), (b["rows"] as JsonArray ?? []).Select(Cells).ToList()));
            else if (t == "metrics")
                outp.Add((title.Length > 0 ? title : "Figures", ["Measure", "Value", "Note"],
                    (b["items"] as JsonArray ?? []).OfType<JsonObject>().Select(i => (IList<object?>)[J.S(i["label"]), J.S(i["value"]), J.S(i["hint"])]).ToList()));
            else if (t == "chart")
            {
                var series = (b["series"] as JsonArray ?? []).OfType<JsonObject>().ToList();
                var cols = new List<string> { title.Length > 0 ? title : "Label" };
                cols.AddRange(series.Select(s => J.S(s["name"])));
                var rows = (b["labels"] as JsonArray ?? []).Select((lbl, i) =>
                {
                    var r = new List<object?> { J.S(lbl) };
                    r.AddRange(series.Select(s => s["values"] is JsonArray v && i < v.Count ? (object?)(J.Double(v[i]) ?? 0) : ""));
                    return (IList<object?>)r;
                }).ToList();
                outp.Add((title.Length > 0 ? title : "Chart data", cols, rows));
            }
        }
        return outp;
    }

    private static string Cell(object? v) => v switch { null => "", double d => d.ToString(Inv), _ => Convert.ToString(v, Inv) ?? "" };

    private static string Esc(object? v) => Cell(v).Replace("|", "\\|").Replace("\n", " ");

    private static string MdTable(IList<string> cols, IList<IList<object?>> rows)
    {
        var lines = new List<string> { "| " + string.Join(" | ", cols.Select(Esc)) + " |", "|" + string.Concat(Enumerable.Repeat("---|", cols.Count)) };
        lines.AddRange(rows.Select(r => "| " + string.Join(" | ", r.Select(Esc)) + " |"));
        return string.Join("\n", lines);
    }

    private static IEnumerable<JsonObject> Blocks(JsonObject m) => (m["blocks"] as JsonArray ?? []).OfType<JsonObject>();

    public static string Markdown(IList<JsonObject> messages, string title)
    {
        var parts = new List<string> { $"# {title}", $"_Exported {Now("dd MMM yyyy, hh:mm tt")} IST_", "" };
        foreach (var m in messages)
        {
            var user = J.S(m["role"]) == "user";
            parts.Add($"## {(user ? "You" : "Assistant")}");
            if (user) parts.Add(J.S(m["text"]));
            foreach (var b in Blocks(m))
            {
                switch (J.S(b["type"]))
                {
                    case "text": parts.Add(J.S(b["text"])); break;
                    case "table" or "metrics" or "chart":
                        foreach (var (name, cols, rows) in Tables([b])) parts.AddRange([$"**{name}**", "", MdTable(cols, rows), ""]);
                        break;
                    case "file": parts.Add($"Download: {J.S(b["title"])} ({J.S(b["format"]).ToUpperInvariant()})"); break;
                    case "action": parts.Add($"Action: {J.S(b["summary"])} — {J.S(b["status"])}"); break;
                    case "error": parts.Add($"> {J.S(b["text"])}"); break;
                }
            }
            parts.Add("");
        }
        return string.Join("\n", parts);
    }

    public static byte[] Build(string fmt, IList<JsonObject> messages, string title, string brand)
    {
        var blocks = messages.SelectMany(Blocks).ToList();
        if (fmt == "json")
            return Encoding.UTF8.GetBytes(J.O(("title", title), ("messages", J.A(messages.Select(m => (object?)m)))).ToJsonString(new JsonSerializerOptions
                { WriteIndented = true, Encoder = J.Relaxed.Encoder }));
        if (fmt == "md") return Encoding.UTF8.GetBytes(Markdown(messages, title));
        var tables = Tables(blocks);
        if (fmt == "csv")
        {
            var sb = new StringBuilder();
            void Row(IEnumerable<object?> cells) => sb.Append(string.Join(",", cells.Select(c =>
            {
                var s = Cell(c);
                if (s.Length > 0 && ("=+@".Contains(s[0]) || (s[0] == '-' && !(s.Length > 1 && char.IsDigit(s[1]))))) s = "'" + s; // formula guard
                return s.IndexOfAny([',', '"', '\n', '\r']) >= 0 ? "\"" + s.Replace("\"", "\"\"") + "\"" : s;
            }))).Append("\r\n");
            if (tables.Count == 0)
            {
                Row(["Text"]);
                foreach (var b in blocks.Where(b => J.S(b["type"]) == "text")) Row([J.S(b["text"])]);
            }
            for (var i = 0; i < tables.Count; i++)
            {
                var (name, cols, rows) = tables[i];
                if (i > 0) sb.Append("\r\n");
                if (tables.Count > 1) Row([name]);
                Row(cols);
                foreach (var r in rows) Row(r);
            }
            return [0xEF, 0xBB, 0xBF, .. Encoding.UTF8.GetBytes(sb.ToString())];
        }
        if (fmt == "xlsx")
        {
            var sheets = tables.ToList();
            var texts = blocks.Where(b => J.S(b["type"]) == "text").Select(b => (IList<object?>)[J.S(b["text"])]).ToList();
            if (texts.Count > 0) sheets.Add(("Answer", ["Text"], texts));
            return DocGen.XlsxBytes(sheets, [("Title", title), ("Exported", Now("dd MMM yyyy HH:mm") + " IST")], brand);
        }
        var doc = new DocGen.PdfDoc(title, $"Exported {Now("dd MMM yyyy, hh:mm tt")} IST");
        foreach (var m in messages)
        {
            if (J.S(m["role"]) == "user")
            {
                doc.Heading("Question");
                doc.Text(J.S(m["text"]));
                continue;
            }
            doc.Heading("Answer");
            foreach (var b in Blocks(m))
            {
                switch (J.S(b["type"]))
                {
                    case "text": doc.Text(J.S(b["text"])); break;
                    case "metrics":
                        if (J.S(b["title"]).Length > 0) doc.Heading(J.S(b["title"]));
                        doc.Metrics((b["items"] as JsonArray ?? []).OfType<JsonObject>().Select(i => (J.S(i["label"]), J.S(i["value"]))).ToList());
                        break;
                    case "table":
                        if (J.S(b["title"]).Length > 0) doc.Heading(J.S(b["title"]));
                        doc.Table((b["columns"] as JsonArray ?? []).Select(J.S).ToList(), (b["rows"] as JsonArray ?? []).Select(Cells).ToList(), (int?)J.Long(b["total_rows"]));
                        break;
                    case "chart":
                        doc.Heading(J.S(b["title"]) is { Length: > 0 } ct ? ct : "Chart");
                        doc.Chart(J.S(b["kind"]) is { Length: > 0 } k ? k : "bar", (b["labels"] as JsonArray ?? []).Select(J.S).ToList(),
                            (b["series"] as JsonArray ?? []).OfType<JsonObject>().Select(s => (J.S(s["name"]), (IList<double>)(s["values"] as JsonArray ?? []).Select(v => J.Double(v) ?? 0).ToList())).ToList());
                        break;
                    case "file":
                        doc.Note($"Download offered: {J.S(b["title"])} ({J.S(b["format"]).ToUpperInvariant()}) — {J.S(b["detail"])}");
                        break;
                    case "action": doc.Note($"Action: {J.S(b["summary"])} — {J.S(b["status"])}"); break;
                    case "error": doc.Note(J.S(b["text"])); break;
                }
            }
        }
        return DocGen.PdfBytes(doc, brand);
    }
}
